class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 1
        self.rolls_in_frame = 0
        self.first_roll = 0
        self.complete = False

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception("Cannot roll more or less than 10 pins")
        if self.complete:
            raise Exception("Cannot roll after game is complete")

        self.rolls.append(pins)

        if self.frame < 10:
            if self.rolls_in_frame == 0:
                self.first_roll = pins
                if pins == 10:
                    self._advance_frame()
                else:
                    self.rolls_in_frame = 1
            else:
                if self.first_roll + pins > 10:
                    raise Exception("Frame cannot score more than 10 points")
                self._advance_frame()
        else:
            if self.rolls_in_frame == 0:
                self.first_roll = pins
                self.rolls_in_frame = 1
            elif self.rolls_in_frame == 1:
                if self.first_roll == 10:
                    # Second roll is a fresh frame; a strike leaves no pins.
                    self.first_roll = 0 if pins == 10 else pins
                elif self.first_roll + pins == 10:
                    # Spare: the bonus roll is a fresh frame.
                    self.first_roll = 0
                else:
                    self.complete = True
                    return
                self.rolls_in_frame = 2
            else:
                if self.first_roll + pins > 10:
                    raise Exception("Frame cannot score more than 10 points")
                self.complete = True

    def _advance_frame(self):
        self.frame += 1
        self.rolls_in_frame = 0
        self.first_roll = 0
        if self.frame > 10:
            self.complete = True

    def score(self):
        if not self.complete:
            raise Exception("Game is not complete")

        total = 0
        i = 0
        for _ in range(10):
            if self.rolls[i] == 10:
                total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                i += 1
            elif self.rolls[i] + self.rolls[i + 1] == 10:
                total += 10 + self.rolls[i + 2]
                i += 2
            else:
                total += self.rolls[i] + self.rolls[i + 1]
                i += 2
        return total
